-- 07_insertion_periode_4.sql - Portrait de l'Âme (Périodes 4A et 4B)
-- ═══════════════════════════════════════════════════════════════════════════

INSERT INTO cycle_vie_soul_periods (
    period_number, polarity, date_start, date_end, period_name, period_title,
    description_general, traits_positifs, traits_vigilance, professions_favorables,
    sante_vigilance, pays_affinites, conseils, message_cosmique, is_active
) VALUES 
-- PÉRIODE 4A
(4, 'A', '06-22', '07-22', 'Les Sages', 'L''Âme Sage Érudite',
E'Vous portez en vous les traces d''incarnations passées où vous avez atteint de hauts pouvoirs personnels et des positions de leadership liées à l''éducation, aux arts nobles, et au développement de la civilisation.\n\nCes expériences ont développé en vous des facultés exceptionnelles pour l''étude, l''acquisition de connaissances, et l''expression de vos idées. Votre mémoire est remarquable, votre capacité de raisonnement exceptionnelle.\n\nVous êtes difficile à connaître objectivement, car vos capacités intellectuelles vous permettent de vous adapter parfaitement à votre environnement. Vous savez rencontrer chaque personne à son niveau.',
E'**L''Intelligence Polyvalente**\nVous pouvez vous adapter à n''importe quelle situation, apprendre n''importe quel sujet, communiquer avec n''importe qui.\n\n**La Mémoire Prodigieuse**\nLes informations, les détails, les connexions — tout reste gravé dans votre esprit avec une clarté remarquable.\n\n**Le Raisonnement Logique**\nVous avez la capacité de présenter vos pensées de manière systématique et convaincante.\n\n**L''Imagination Créatrice**\nCombinée à votre tempérance et votre idéalisme mystique, votre imagination devient un outil puissant.',
E'**La Tendance à l''Imaginaire**\nL''imagination peut créer des idées que vous présentez comme vraies.\n\n**L''Agitation Intellectuelle**\nCette recherche constante du nouveau peut vous faire ignorer le pratique.\n\n**Le Surmenage Mental**\nVotre système nerveux et mental pourrait ne pas supporter la tension.',
E'**Les Métiers du Savoir**\n• Professeur d''université ou chercheur\n• Mathématicien(ne) ou scientifique\n• Écrivain ou éditeur\n• Poète ou orateur\n\n**Les Métiers de la Guidance**\n• Guide spirituel ou mentor\n• Sculpteur ou artiste conceptuel\n• Banquier ou financier\n• Ambassadeur ou diplomate',
E'• Vertiges et fatigues cérébrales\n• Léger bégaiement ou imperfections d''élocution\n• Enrouement et toux sèche\n• Rhumes de tête et sinus',
E'Votre âme résonne particulièrement avec :\n• La Flandre et ses traditions intellectuelles\n• L''Égypte et ses mystères anciens\n• L''Inde et sa sagesse millénaire\n• Le Sud de la France et sa lumière',
E'1. **Canalisez Votre Imagination** — Transformez-la en création plutôt qu''en fuite.\n2. **Partagez Votre Savoir** — La connaissance non partagée s''atrophie.\n3. **Équilibrez l''Intellectuel et le Pratique** — Ancrez vos hautes pensées dans le réel.\n4. **Protégez Votre Système Nerveux** — Accordez-vous des temps de repos mental.',
E'Vous êtes venu(e) dans cette vie pour être un gardien de la connaissance et un pont entre les traditions anciennes et le monde moderne. Votre mission est d''éclairer les chemins obscurs avec la lumière de votre compréhension. Mais n''oubliez pas que la sagesse suprême est de savoir que l''on ne sait rien.',
true),

-- PÉRIODE 4B
(4, 'B', '06-22', '07-22', 'Les Harmonieux', 'L''Âme Harmonieuse Équilibrée',
E'Vous êtes particulièrement doué(e) pour utiliser vos capacités mentales et votre raisonnement logique dans la prise de décisions et l''atteinte de conclusions raisonnables.\n\nCette quête d''équilibre se manifeste dans tous les aspects de votre vie. Quand vous examinez des preuves ou des déclarations sur un sujet, vous cherchez toujours le point médian.\n\nVous êtes bien équilibré(e) dans toutes vos facultés et avez un grand désir d''équilibrer toutes vos pensées et connaissances. Cette tendance se reflète dans votre mode de vie qui est généralement esthétique.',
E'**Le Sens de la Balance**\nVous savez instinctivement trouver le point d''équilibre dans toute situation.\n\n**Le Jugement Équilibré**\nVos décisions sont rarement extrêmes ou impulsives.\n\n**L''Appréciation Esthétique**\nVous avez un œil naturel pour la beauté et l''harmonie.\n\n**La Tranquillité d''Esprit**\nVous traversez la vie avec une égalité d''humeur et une sérénité.',
E'**L''Indécision Paralysante**\nCette capacité à voir tous les côtés peut parfois vous empêcher de prendre une décision ferme.\n\n**L''Évitement du Conflit**\nVotre amour de l''harmonie peut vous conduire à éviter les confrontations nécessaires.\n\n**Le Perfectionnisme Esthétique**\nVotre désir de beauté peut parfois vous rendre trop exigeant(e).',
E'**Les Métiers de la Médiation**\n• Juge ou arbitre\n• Médiateur(trice) ou conciliateur(trice)\n• Diplomate ou négociateur(trice)\n• Conseiller(ère) conjugal(e) ou familial(e)\n\n**Les Métiers de la Beauté**\n• Artiste ou designer\n• Architecte d''intérieur\n• Créateur(trice) de mode\n• Directeur(trice) artistique',
E'• Vertiges et fatigues cérébrales\n• Difficultés d''élocution passagères\n• Rhumes et affections des voies respiratoires',
E'Comme vos proches cosmiques :\n• La Flandre et l''Égypte\n• L''Inde et le Sud de la France\n• Tout lieu où la beauté et l''harmonie prédominent',
E'1. **Acceptez Que l''Équilibre Parfait N''existe Pas** — La vie est en mouvement constant.\n2. **Osez Prendre Position** — Parfois, la neutralité n''est pas une option.\n3. **Créez de la Beauté Autour de Vous** — C''est votre façon de contribuer au monde.\n4. **Guidez les Enfants et les Jeunes** — Votre sens de l''équilibre peut les aider à trouver leur chemin.',
E'Vous êtes venu(e) dans cette vie pour apporter l''équilibre dans un monde souvent chaotique. Votre mission est de créer des espaces de paix, de beauté et de justice partout où vous passez. Rappelez-vous que l''harmonie n''est pas l''absence de conflit, mais la résolution créative des tensions.',
true);

SELECT '✅ PÉRIODE 4 (4A + 4B) INSÉRÉE' as status;
